INSERT INTO public.kb_articles (
  slug, category_id, title_ar, title_en, excerpt_ar, excerpt_en, content_ar,
  meta_title, meta_description, keywords, reading_minutes, faq, "references",
  external_sources, author_name, is_featured, status, generation_source, published_at
) VALUES
('ifrs-18-financial-statements-practical-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'international-accounting-standards'),
  'دليل إعداد القوائم المالية وفق IFRS 18 خطوة بخطوة',
  'IFRS 18 Financial Statements: A Practical Guide',
  'دليل تطبيقي حول إعداد القوائم المالية IFRS 18 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to ifrs 18 financial statements: a practical guide, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع إعداد القوائم المالية IFRS 18 يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "ابدأ بخريطة تربط حسابات الأستاذ بفئات التشغيل والاستثمار والتمويل، ووثق الأحكام للحسابات المختلطة."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: تصنيف الدخل والمصروفات، المجاميع الفرعية ومقاييس الأداء، وخطة التحول والبيانات.", "اختبر قائمة الأرباح أو الخسائر المقارنة، واضبط تسويات مقاييس الأداء المحددة من الإدارة قبل اعتماد العرض."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'إعداد القوائم المالية IFRS 18 | دليل عملي للمحاسبين',
  'دليل تطبيقي حول إعداد القوائم المالية IFRS 18 يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['إعداد القوائم المالية IFRS 18','تصنيف الدخل والمصروفات','المجاميع الفرعية ومقاييس الأداء','خطة التحول والبيانات'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق إعداد القوائم المالية IFRS 18؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ifrs-18-presentation-and-disclosure-in-financial-statements/"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ifrs-18-presentation-and-disclosure-in-financial-statements/"}]$sources$::jsonb,
  'أحمد المدني',
  false,
  'published',
  'editorial',
  '2026-08-30 08:00:00+03'::timestamptz),
('accounting-profit-vs-taxable-profit',
  (SELECT id FROM public.kb_categories WHERE slug = 'tax-accounting'),
  'الفرق بين الربح المحاسبي والربح الضريبي وكيفية إعداد التسوية',
  'Accounting Profit vs Taxable Profit',
  'دليل تطبيقي حول الربح المحاسبي والربح الضريبي يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to accounting profit vs taxable profit, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع الربح المحاسبي والربح الضريبي يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "ينطلق الربح المحاسبي من المعايير والسياسات المحاسبية، بينما يتحدد الوعاء الضريبي وفق النظام واللائحة المطبقة."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: لماذا يختلف الربحان؟، الفروق الدائمة والمؤقتة، وورقة التسوية الضريبية.", "صنف الفروق إلى دائمة ومؤقتة، واربط كل تعديل بحساب ومستند وسند نظامي وموافقة واضحة."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'الربح المحاسبي والربح الضريبي | دليل عملي للمحاسبين',
  'دليل تطبيقي حول الربح المحاسبي والربح الضريبي يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['الربح المحاسبي والربح الضريبي','لماذا يختلف الربحان؟','الفروق الدائمة والمؤقتة','ورقة التسوية الضريبية'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق الربح المحاسبي والربح الضريبي؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/RulesRegulations/Taxes/Pages/IncomeTax.aspx"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/RulesRegulations/Taxes/Pages/IncomeTax.aspx"}]$sources$::jsonb,
  'أحمد المدني',
  false,
  'published',
  'editorial',
  '2026-08-30 08:10:00+03'::timestamptz),
('cash-flow-statement-preparation-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'financial-statements'),
  'كيفية إعداد قائمة التدفقات النقدية من ميزان المراجعة',
  'How to Prepare a Cash Flow Statement',
  'دليل تطبيقي حول إعداد قائمة التدفقات النقدية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to how to prepare a cash flow statement, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع إعداد قائمة التدفقات النقدية يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "تبدأ الطريقة غير المباشرة من الربح ثم تعدله بالبنود غير النقدية وتغيرات رأس المال العامل."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: الطريقة المباشرة وغير المباشرة، تصنيف التدفقات النقدية، ومراجعة وربط القائمة.", "طابق صافي التغير في النقد مع رصيدي البداية والنهاية، وراجع المعاملات غير النقدية والإفصاحات المرتبطة بها."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'إعداد قائمة التدفقات النقدية | دليل عملي للمحاسبين',
  'دليل تطبيقي حول إعداد قائمة التدفقات النقدية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['إعداد قائمة التدفقات النقدية','الطريقة المباشرة وغير المباشرة','تصنيف التدفقات النقدية','مراجعة وربط القائمة'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق إعداد قائمة التدفقات النقدية؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ias-7-statement-of-cash-flows/"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://www.ifrs.org/issued-standards/list-of-standards/ias-7-statement-of-cash-flows/"}]$sources$::jsonb,
  'أحمد المدني',
  false,
  'published',
  'editorial',
  '2026-08-30 08:20:00+03'::timestamptz),
('saudi-vat-practical-guide',
  (SELECT id FROM public.kb_categories WHERE slug = 'vat'),
  'دليل ضريبة القيمة المضافة في السعودية: التسجيل والإقرار والمطابقة',
  'Saudi VAT: Registration, Filing, and Reconciliation',
  'دليل تطبيقي حول ضريبة القيمة المضافة السعودية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to saudi vat: registration, filing, and reconciliation, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع ضريبة القيمة المضافة السعودية يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "حدد حالة التسجيل والفترة الضريبية من ملف المكلف، ولا تعتمد على افتراضات عامة عند تحديد موعد الإقرار."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: التسجيل والفترات الضريبية، ضريبة المخرجات والمدخلات، والمطابقة قبل الإقرار.", "طابق دفتر الأستاذ مع المبيعات والمشتريات والإشعارات ومنصة فاتورة قبل اعتماد الإقرار والسداد."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'ضريبة القيمة المضافة السعودية | دليل عملي للمحاسبين',
  'دليل تطبيقي حول ضريبة القيمة المضافة السعودية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  ARRAY['ضريبة القيمة المضافة السعودية','التسجيل والفترات الضريبية','ضريبة المخرجات والمدخلات','المطابقة قبل الإقرار'],
  5,
  $faq$[{"q": "ما أول خطوة لتطبيق ضريبة القيمة المضافة السعودية؟", "a": "تحديد الهدف والنطاق ومصدر البيانات والمسؤول عن الإعداد والمراجعة قبل بدء الحساب أو الترحيل."}, {"q": "كيف أتأكد من جودة النتيجة؟", "a": "بالمطابقة مع مصدر مستقل، ومراجعة الاستثناءات، وتوثيق الافتراضات والحسابات والموافقات."}, {"q": "هل يكفي استخدام نموذج جاهز؟", "a": "لا؛ يجب تكييف النموذج مع نشاط المنشأة وسياساتها وأنظمتها والمتطلبات النظامية أو المعيارية السارية."}]$faq$::jsonb,
  $refs$[{"label": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/RulesRegulations/Taxes/Pages/VAT.aspx"}]$refs$::jsonb,
  $sources$[{"name": "المصدر المرجعي", "url": "https://zatca.gov.sa/ar/RulesRegulations/Taxes/Pages/VAT.aspx"}]$sources$::jsonb,
