('real-estate-transaction-tax-exemptions',
  (SELECT id FROM public.kb_categories WHERE slug = 'zakat-tax-ksa'),
  'ضريبة التصرفات العقارية: الاحتساب والتسجيل والاستثناءات',
  'Real Estate Transaction Tax: Calculation and Exemptions',
  'دليل تطبيقي حول ضريبة التصرفات العقارية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
  'A practical guide to real estate transaction tax: calculation and exemptions, implementation steps, common errors, and a working checklist.',
  $article$[{"heading": "مقدمة عملية", "paragraphs": ["يقدم هذا الدليل إطاراً عملياً لموضوع ضريبة التصرفات العقارية يساعد المحاسب على الانتقال من الفهم النظري إلى إجراء موثق وقابل للمراجعة.", "سجل التصرف واحسب الالتزام قبل الإفراغ أو التوثيق وفق الإجراء المعتمد، واحتفظ بالرقم المرجعي."]}, {"heading": "خطوات التطبيق", "paragraphs": ["ابدأ بتحديد نطاق العمل والبيانات والمالك، ثم طبق الخطوات على عينة قبل التعميم. وتشمل محاور التنفيذ: متى تنشأ الضريبة؟، فحص الاستثناءات، وملف المستندات.", "لا تطبق الاستثناء بالاسم فقط؛ افحص أطراف التصرف والغرض والمقابل والمستندات والشروط النظامية مجتمعة."]}, {"heading": "أخطاء شائعة", "paragraphs": ["من أكثر الأخطاء شيوعاً الاعتماد على قالب سابق دون فحص تغير البيانات أو السياسات، وغياب الربط بين النتيجة ومصدرها، وتأجيل مراجعة الاستثناءات إلى نهاية الفترة.", "استخدم مراجعة مستقلة وقائمة استثناءات، وحدد حدود الأهمية النسبية، واحتفظ بدليل يوضح المدخلات والحساب والموافقة."]}, {"heading": "قائمة فحص تنفيذية", "paragraphs": ["1. **حدد الهدف والنطاق:** ما القرار أو التقرير الذي سيستخدم النتيجة؟", "2. **تحقق من المصدر:** اربط كل رقم بالنظام أو المستند المسؤول عنه.", "3. **اختبر الاستثناءات:** راجع الحالات غير المعتادة والفروق الكبيرة.", "4. **وثق واعتمد:** احفظ الحساب والمراجعة والموافقة وخطة المتابعة."]}]$article$::jsonb,
  'ضريبة التصرفات العقارية | دليل عملي للمحاسبين',
  'دليل تطبيقي حول ضريبة التصرفات العقارية يشمل خطوات التنفيذ والأخطاء الشائعة وقائمة فحص قابلة للاستخدام في العمل المحاسبي.',
